package com.localbiz.model;
public class CustomerLocation { private int locationId,userId,cityId,areaId; private String addressLine,pincode; private boolean primary;
 public int getLocationId(){return locationId;} public void setLocationId(int v){locationId=v;} public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public int getCityId(){return cityId;} public void setCityId(int v){cityId=v;} public int getAreaId(){return areaId;} public void setAreaId(int v){areaId=v;} public String getAddressLine(){return addressLine;} public void setAddressLine(String v){addressLine=v;} public String getPincode(){return pincode;} public void setPincode(String v){pincode=v;} public boolean isPrimary(){return primary;} public void setPrimary(boolean v){primary=v;} }
